import {makeStainedMapSource,stainedMapCopy as T} from './stained-map-content.mjs';
import * as C from './stained-map-core.mjs';
import {storyView} from './keeper-story-core.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const p=(x,read=false)=>`<p${read?' data-sm-read':''}>${esc(x)}</p>`;
const text=x=>typeof x==='string'?x:'';
const paragraphs=x=>Array.isArray(x)?x.filter(y=>typeof y==='string'):[];
const button=(action,label,attrs='',disabled=false)=>`<button type="button" data-sm-action="${action}" ${attrs}${disabled?' disabled':''}>${esc(label)}</button>`;
let views=new WeakMap();
export function resetStainedMapView(){views=new WeakMap();}
function local(state,owner){let l=views.get(state);if(!l||l.owner!==owner||l.root!==state.spellings){l={owner,root:state.spellings,selected:{},steps:{},panels:[],longer:false,notice:'',noticePage:null};views.set(state,l);}return l;}
const spoken=x=>String(x).replaceAll('▢▢',' '+T.spokenTwoStains+' ').replaceAll('▢',' '+T.spokenOneStain+' ').replace(/\s+/g,' ').trim();
const pageKey=v=>v.view==='practice'?'practice/'+(v.current?.id??''):v.view;
const disclosure=(l,id,title,body)=>`<details data-sm-panel="${esc(id)}"${l.panels.includes(id)?' open':''}><summary>${esc(title)}</summary>${body}</details>`;
const unavailable=message=>`<aside class="sm-notice">${p(message)}<a href="#notes">${esc(T.notes)}</a></aside>`;
const placement=(w,k)=>Object.hasOwn(w.placements,k)?w.placements[k]:null;
const choiceLabel=(s,id)=>s.choices.find(x=>x.id===id)?.text??T.unselected;
const selectedLabel=(s,w,part)=>s.kind==='map'?C.stainedLabel(part,s.choices.find(x=>x.id===placement(w,part.id))):part.word??part.text;
function valley(){return `<svg class="sm-valley" viewBox="0 0 540 350" aria-hidden="true"><path d="M0 0h540v350H0z" fill="#edf4ef"/><path d="M0 124 85 44l87 90 108-111 122 116 83-74 55 52v91H0Z" fill="#c3d3c2"/><path d="m154 110 18 24 108-111 34 36-38-15-21 28-20-5-63 88Z" fill="#f8fbf8"/><path d="M269 93q-98 59-48 111t-35 146" fill="none" stroke="#90b7c7" stroke-width="33"/><path d="M0 275q75-108 154-16t171-12 215-30v133H0Z" fill="#d6e1cb"/><path d="m26 199 116-25 112 58 95-21 168 91M106 323l30-149 6-72" fill="none" stroke="#b5a27c" stroke-width="4" stroke-dasharray="7 6"/><path d="m192 172 52-9m-48 24 52-9" stroke="#626e68" stroke-width="5"/><g fill="#658263"><path d="m58 153 15-38 15 38Zm31 5 17-45 17 45Zm-53 10 13-31 13 31Z"/><path d="m377 154 15-38 15 38Zm31 5 17-45 17 45Zm-53 10 13-31 13 31Z"/></g><ellipse cx="427" cy="277" rx="34" ry="19" fill="#91b5bd"/><path d="m324 278 18-19 18 19v23h-36Z" fill="#aabbaa" stroke="#547250" stroke-width="2"/><path d="M9 9h522v332H9Z" fill="none" stroke="#78918b" stroke-width="2"/></svg>`;}
function workReadout(s,w){
 if(s.kind==='choice')return p(choiceLabel(s,w.choice));
 return `<dl class="sm-readout">${s.parts.map(part=>`<div><dt>${esc(s.kind==='map'?C.stainedLabel(part,null):part.word??part.text)}</dt><dd>${esc(s.kind==='map'?selectedLabel(s,w,part):choiceLabel(s,placement(w,part.id)))}${p(T.chosen.replace('{tile}',choiceLabel(s,placement(w,part.id))))}</dd></div>`).join('')}</dl>`;
}
function checks(entry){return entry.last?`<aside id="sm-feedback" tabindex="-1" class="sm-feedback" aria-label="Earlier check">${entry.earlier?p(T.earlierCheck):''}${entry.last.feedback.map(x=>p(x)).join('')}</aside>`:'';}
function keeps(entry,l){return ['first','latest'].map(edition=>{
 const key=edition+'Kept',snapshot=entry.record[key],label=edition==='first'?T.firstKept:T.latestKept,status=entry[edition+'Status'];
 if(status==='missing'||snapshot===null)return '';
 if(status!=='ready')return unavailable(T.unsupportedRecord);
 return disclosure(l,'keep-'+edition,label,`${button('inspect',T.inspectSnapshot,`data-sm-edition="${edition}"`)}${l.inspect===edition?`${workReadout(entry.source,snapshot.work)}${snapshot.check?snapshot.check.feedback.map(x=>p(x)).join(''):p(T.unchecked)}`:''}${button('restore',T.restoreSnapshot,`data-sm-edition="${edition}"`)}`);
 }).join('');}
const stepCount=(l,id,fallback=0)=>Object.hasOwn(l.steps,id)?l.steps[id]:fallback;
function worked(card,l){const n=Math.min(stepCount(l,card.id,1),card.steps.length);return `<section class="sm-worked" tabindex="-1">${p(card.title)}${p(card.text,true)}${p(card.example,true)}<ol>${card.steps.slice(0,n).map(step=>`<li data-sm-read>${esc(step)}</li>`).join('')}</ol><div class="sm-actions">${button('step-back',T.previous,`data-sm-card="${esc(card.id)}"`,n===0)}${button('step',T.nextStep,`data-sm-card="${esc(card.id)}"`,n===card.steps.length)}</div></section>`;}
function teaching(cards,l){return cards.map(card=>{const n=Math.min(stepCount(l,card.id),card.steps.length);return disclosure(l,'teach-'+card.id,card.title,`${p(card.text,true)}${p(card.example,true)}<ol>${card.steps.slice(0,n).map(step=>`<li data-sm-read>${esc(step)}</li>`).join('')}</ol><div class="sm-actions">${button('step-back',T.previous,`data-sm-card="${esc(card.id)}"`,n===0)}${button('step',T.nextStep,`data-sm-card="${esc(card.id)}"`,n===card.steps.length)}</div>`);}).join('');}
function bench(entry,kind,l){
 if(!entry||entry.status!=='ready'||entry.draftStatus!=='ready')return unavailable(T.unsupportedRecord);
 const s=entry.source,w=entry.record.work,part=s.parts.find(x=>x.id===l.selected[kind])??s.parts[0];
 const selection=placement(w,part.id)??null;
 const instruction=kind==='map'?T.mapInstruction:kind==='histories'?T.historyInstruction:T.familyInstruction;
 const picker=kind==='map'?T.mapPicker:kind==='histories'?T.historyPicker:T.familyPicker;
 const positions=kind==='map'?`<div class="sm-map">${valley()}<div class="sm-map-labels">${s.parts.map(x=>button('select',C.stainedLabel(x,s.choices.find(t=>t.id===placement(w,x.id)))+' — '+T.chosen.replace('{tile}',choiceLabel(s,placement(w,x.id))),`data-sm-part="${esc(x.id)}" aria-label="${esc(spoken(C.stainedLabel(x,s.choices.find(t=>t.id===placement(w,x.id))))+' — '+T.chosen.replace('{tile}',choiceLabel(s,placement(w,x.id))))}" aria-pressed="${x.id===part.id}"`)).join('')}</div></div>`:'';
 const note=kind==='families'?disclosure(l,'family-'+part.id,T.familyNote,p(part.word+' → '+choiceLabel(s,part.key))):p(part.note,true);
 return `<section class="sm-bench"><h2 id="sm-task" tabindex="-1">${esc(T[kind+'Title'])}</h2>${p(instruction,true)}<div class="sm-workspace">${positions}<div class="sm-current"><label>${esc(picker)}<select data-sm-picker>${s.parts.map(x=>`<option value="${esc(x.id)}" aria-label="${esc(kind==='map'?spoken(C.stainedLabel(x,null)):x.word)}"${x.id===part.id?' selected':''}>${esc(kind==='map'?C.stainedLabel(x,null):x.word)}</option>`).join('')}</select></label><div class="sm-name">${esc(selectedLabel(s,w,part))}</div>${kind==='families'?p(part.letter):''}<aside class="sm-written-note"><strong>Written note</strong>${note}</aside>${p(T.chosen.replace('{tile}',choiceLabel(s,selection)))}<div class="sm-tray" role="group" aria-label="${esc(picker)}">${s.choices.map(x=>button('place',x.text,`data-sm-choice="${esc(x.id)}" aria-pressed="${selection===x.id}"`)).join('')}</div><div class="sm-actions">${button('put-back',T.putBack,'',selection===null)}${button('previous',T.previous,'',s.parts.indexOf(part)===0)}${button('next',T.next,'',s.parts.indexOf(part)===s.parts.length-1)}</div></div></div>${kind!=='map'?`<div class="sm-placements">${s.parts.map(x=>button('select',x.word+' — '+choiceLabel(s,placement(w,x.id)),`data-sm-part="${esc(x.id)}" aria-pressed="${x.id===part.id}"`)).join('')}</div>`:''}${s.retainedUnreadable||entry.retainedUnreadable?unavailable(T.unavailableSelection):''}${controls(entry)}${checks(entry)}${keeps(entry,l)}</section>`;
}
function controls(entry){return `<div class="sm-actions sm-commit">${button('check',T.check,'',entry.checksStatus==='unreadable')}${button('keep',T.keep,'',entry.latestStatus==='unreadable')}</div>`;}
function practice(v,l){
 const shelf=`<div class="sm-jobs" role="group" aria-label="Choose a job">${v.jobs.map((j,i)=>button('job',j.source?.title||T.practiceTitle,`data-sm-job="${esc(j.id)}" aria-pressed="${v.current?.id===j.id}"`,['unavailable','unreadable'].includes(j.status))).join('')}</div>`;
 const e=v.current;if(!e)return `<section><h2 id="sm-task" tabindex="-1">${esc(T.practiceTitle)}</h2>${shelf}</section>`;
 if(e.status!=='ready'||e.draftStatus!=='ready'||e.helpStatus!=='ready')return shelf+unavailable(T.unsupportedRecord);
 const s=e.source,w=e.record.work,part=s.parts.find(p=>p.id===l.selected[s.id])??s.parts[0];
 const work=s.kind==='choice'?`<div class="sm-tray">${s.choices.map(x=>button('answer',x.text,`data-sm-choice="${esc(x.id)}" aria-pressed="${w.choice===x.id}"`)).join('')}</div>`:`<div class="sm-job-parts">${s.parts.map(x=>button('select-job',x.text+' — '+choiceLabel(s,placement(w,x.id)),`data-sm-part="${esc(x.id)}" aria-pressed="${part.id===x.id}"`)).join('')}</div><div class="sm-selected">${p(part.text,true)}<div class="sm-tray">${s.choices.map(x=>button('answer',x.text,`data-sm-choice="${esc(x.id)}" aria-pressed="${placement(w,part.id)===x.id}"`)).join('')}</div></div>`;
 return `<section><h2 id="sm-task" tabindex="-1">${esc(s.title)}</h2>${shelf}${p(s.prompt,true)}${s.kind==='choice'&&s.parts.length?`<ul class="sm-job-notes">${s.parts.map(part=>`<li data-sm-read>${esc(part.text)}</li>`).join('')}</ul>`:''}${s.steps.length?`<ol>${s.steps.map(x=>`<li data-sm-read>${esc(x)}</li>`).join('')}</ol>`:''}${work}${button('put-back',T.putBack,'',s.kind==='choice'?w.choice===null:placement(w,part.id)===null)}<div class="sm-actions">${button('hint',T.hint)}${button('example',T.example)}${button('skip',T.skip)}</div>${e.record.help.hint?`<p id="sm-hint" tabindex="-1" data-sm-read>${esc(s.hint)}</p>`:''}${e.record.help.example?s.teach.map(card=>worked(card,l)).join(''):''}${controls(e)}${checks(e)}${keeps(e,l)}${e.retainedUnreadable?unavailable(T.unavailableSelection):''}${!e.record.help.example?teaching(s.teach,l):''}</section>`;
}
export function stainedMapEntry(){return `<a class="secondary" href="#library/spellings">${esc(T.title)}</a>`;}
export function stainedMapPage(state,owner='',guide='your guide'){
 const v=C.stainedMapView(state),l=local(state,owner),source=v.status==='new'?makeStainedMapSource():v.source;
 const header=`<header class="sm-heading"><a href="#words">${esc(T.wordGarden)}</a><h1>${esc(T.placeTitle)}</h1><p>${esc(T.title)}</p></header>`;
 if(v.status==='unsupported')return `<section class="sm-room" data-stained-map-root>${header}${unavailable(T.unsupportedNotebook)}</section>`;
 const context=storyView(state).pageVisible?'after':'before',story=source?.story?.[context];
 const storyBody=story?`${p(T.fiction)}${paragraphs(story.arrival).map(x=>p(x,true)).join('')}${p(text(story.hook),true)}${context==='after'?p(text(story.caption),true):''}<div class="sm-actions">${button('short','Short',`aria-pressed="${!l.longer}"`)}${button('longer','Longer',`aria-pressed="${l.longer}"`)}</div>${paragraphs(story[l.longer?'longer':'short']).map(x=>p(x.replaceAll('{guide}',guide),true)).join('')}${p(T.fact)}${p(text(source.story.note),true)}`:unavailable(T.unavailableSelection);
 const mode=v.view,body=mode==='practice'?practice(v,l):C.stainedMapTables.includes(mode)?`${mode==='map'&&context==='after'?p(text(story?.caption),true):''}${bench(v.tables[mode],mode,l)}`:`<section class="sm-arrival"><h2 id="sm-task" tabindex="-1">${esc(T.title)}</h2>${valley()}${story?`${p(text(story.hook),true)}${context==='after'?p(text(story.caption),true):''}`:''}</section>`;
 return `<section class="sm-room" data-stained-map-root>${header}<nav class="sm-ways" aria-label="Spelling tables">${[...C.stainedMapTables,'practice'].map(k=>button('table',T[k==='practice'?'practiceTitle':k+'Title'],`data-sm-table="${k}" aria-pressed="${mode===k}"`)).join('')}</nav><p class="sm-reminder" data-sm-read>${esc(T.reminder)}</p>${body}<p id="sm-status" role="status" tabindex="-1">${esc(l.noticePage===pageKey(v)?l.notice:'')}</p><p class="sm-saving" data-sm-saving></p><button type="button" data-speak="" class="secondary">${esc(T.readAloud)}</button>${mode!=='practice'?teaching(C.stainedMapCards(source),l):''}${disclosure(l,'story',T.fiction,storyBody)}${disclosure(l,'grownups','For grown-ups',p(T.adultLine)+p(T.adultDetails))}<footer><a href="#library/endings">The Endings Shelf</a><a href="#notes">${esc(T.notes)}</a><a href="#words/signs">${esc(T.marketSigns)}</a></footer></section>`;
}
export function stainedMapNotes(state){
 if(!Object.hasOwn(state,'spellings'))return '';const v=C.stainedMapView(state);
 const entries=[...C.stainedMapTables.map(k=>({id:k,...v.tables[k]})),...v.jobs];
 return `<details class="panel" data-stained-map-notes><summary>${esc(T.title)}: supplied spelling work</summary>${p(T.adultLine)}${p(T.adultDetails)}${v.status!=='ready'?p(T.unsupportedNotebook):entries.filter(e=>e.record).map(e=>`<section><h3>${esc(e.source?.title??T[e.id+'Title']??T.practiceTitle)}</h3>${e.draftStatus==='ready'?workReadout(e.source,e.record.work):p(T.unsupportedRecord)}${e.last?e.last.feedback.map(x=>p(x)).join(''):p(T.unchecked)}${e.source?.v&&e.helpStatus==='ready'?p(`Hint requested: ${e.record.help.hint?'yes':'no'}. Example requested: ${e.record.help.example?'yes':'no'}.`):''}${['first','latest'].map(k=>e[k+'Status']==='ready'&&e.record[k+'Kept']?p(k==='first'?T.firstKept:T.latestKept):'').join('')}</section>`).join('')}<details><summary>Full retained spelling work</summary><pre>${esc(JSON.stringify(state.spellings,null,2))}</pre></details><a href="#library/spellings">${esc(T.title)}</a></details>`;
}
export function bindStainedMap(state,ctx={}){
 const root=document.querySelector('[data-stained-map-root]');if(!root)return;
 const owner=ctx.explorerId?.()??'',l=local(state,owner),owned=state.spellings,material=JSON.stringify(owned),options={canExport:ctx.canExport};
 const live=el=>root.isConnected&&root===document.querySelector('[data-stained-map-root]')&&root.contains(el)&&el.isConnected&&!el.disabled&&!el.closest('[hidden],details:not([open])')&&el.getClientRects().length>0&&getComputedStyle(el).visibility!=='hidden'&&location.hash==='#library/spellings'&&(!ctx.notebook||ctx.notebook()===state)&&(ctx.explorerId?.()??'')===owner&&ctx.isActive?.()!==false&&state.spellings===owned&&JSON.stringify(state.spellings)===material&&views.get(state)===l&&!document.querySelector('dialog.welcome-film[open]');
 const remember=()=>{l.panels=[...root.querySelectorAll('[data-sm-panel][open]')].map(e=>e.dataset.smPanel);};
 const redraw=(target='#sm-task')=>{remember();ctx.stopSpeech?.();ctx.render?.();const next=document.querySelector('[data-stained-map-root]');const requested=next?.querySelector(target),focus=requested&&!requested.disabled&&requested.getClientRects().length?requested:(next?.querySelector('.sm-worked')??next?.querySelector('[data-sm-picker]')??next?.querySelector('#sm-task'));focus?.focus();};
 const commit=(fn,message='',target='#sm-task')=>{const result=fn();if(!result.ok){l.notice=result.error==='capacity'?T.preflightRefusal:T.unavailableSelection;l.noticePage=pageKey(C.stainedMapView(state));return redraw('#sm-status');}l.root=state.spellings;const saved=ctx.save?.();l.notice=[message,saved?.enabled===false||saved?.ok===false?saved.message||'':''].filter(Boolean).join(' ');l.noticePage=pageKey(C.stainedMapView(state));redraw(l.notice?'#sm-status':target);};
 root.querySelector('[data-sm-picker]')?.addEventListener('change',e=>{if(!live(e.currentTarget))return;const v=C.stainedMapView(state);if(!v.tables[v.view]?.source?.parts.some(p=>p.id===e.currentTarget.value))return;l.selected[v.view]=e.currentTarget.value;redraw('[data-sm-picker]');});
 root.querySelectorAll('[data-sm-action]').forEach(el=>el.addEventListener('click',()=>{
  if(!live(el))return;const action=el.dataset.smAction,v=C.stainedMapView(state),practiceMode=v.view==='practice',e=practiceMode?v.current:v.tables[v.view],s=e?.source,selectionKey=practiceMode?s?.id:v.view,part=s?.parts?.find(p=>p.id===l.selected[selectionKey])??s?.parts?.[0];
  if(action==='table'){l.inspect=null;return commit(()=>C.openStainedTable(state,el.dataset.smTable,options));}
  if(action==='job'){l.inspect=null;return commit(()=>C.openStainedJob(state,el.dataset.smJob,options));}
  if(action==='select'||action==='select-job'){if(!s?.parts.some(p=>p.id===el.dataset.smPart))return;l.selected[selectionKey]=el.dataset.smPart;return redraw(action==='select-job'?`[data-sm-action="select-job"][data-sm-part="${el.dataset.smPart}"]`:'[data-sm-picker]');}
  if(action==='next'||action==='previous'){if(!part)return;l.selected[selectionKey]=s.parts[Math.max(0,Math.min(s.parts.length-1,s.parts.indexOf(part)+(action==='next'?1:-1)))].id;return redraw('[data-sm-picker]');}
  if(action==='place'||action==='answer'||action==='put-back'){const pick=action==='put-back'?null:el.dataset.smChoice;return commit(()=>practiceMode?C.answerStainedJob(state,s.id,part?.id,pick,options):C.placeStainedCard(state,v.view,part?.id,pick,options),'',action==='put-back'?(practiceMode?(s.kind==='choice'?'[data-sm-action="answer"]':`[data-sm-action="select-job"][data-sm-part="${part.id}"]`):'[data-sm-picker]'):`[data-sm-action="${action}"][data-sm-choice="${pick}"]`);}
  if(action==='check')return commit(()=>practiceMode?C.checkStainedJob(state,s.id,options):C.checkStainedTable(state,v.view,options),'','#sm-feedback');
  if(action==='keep')return commit(()=>practiceMode?C.keepStainedJob(state,s.id,options):C.keepStainedTable(state,v.view,options),T.kept);
  if(action==='restore')return commit(()=>practiceMode?C.restoreStainedJob(state,s.id,el.dataset.smEdition,options):C.restoreStainedTable(state,v.view,el.dataset.smEdition,options),T.snapshotCopied);
  if(action==='inspect'){l.inspect=el.dataset.smEdition;return redraw(`[data-sm-panel="keep-${l.inspect}"] summary`);}
  if(action==='hint'||action==='example')return commit(()=>C.useStainedHelp(state,s.id,action,options),'',action==='hint'?'#sm-hint':'.sm-worked');
  if(action==='skip'){const at=v.jobs.findIndex(j=>j.id===s.id),next=[...v.jobs.slice(at+1),...v.jobs.slice(0,at+1)].find(j=>['ready','missing'].includes(j.status)&&j.draftStatus!=='unreadable'&&j.helpStatus!=='unreadable');if(next)return commit(()=>C.openStainedJob(state,next.id,options));return;}
  if(action==='short'||action==='longer'){l.longer=action==='longer';return redraw(`[data-sm-action="${action}"]`);}
  if(action==='step'||action==='step-back'){const cards=practiceMode?s?.teach:C.stainedMapCards(v.source??makeStainedMapSource()),card=cards?.find(c=>c.id===el.dataset.smCard);if(!card)return;l.steps[card.id]=Math.max(0,Math.min(card.steps.length,(stepCount(l,card.id,practiceMode&&e.record.help.example?1:0))+(action==='step'?1:-1)));return redraw(practiceMode&&e.record.help.example?`[data-sm-action="${action}"][data-sm-card="${card.id}"]:not(:disabled)`:`[data-sm-panel="teach-${card.id}"] summary`);}
 }));
 root.querySelector('[data-speak]')?.addEventListener('click',event=>{const el=event.currentTarget;if(!live(el)){event.preventDefault();event.stopImmediatePropagation();return;}el.dataset.speak=[...root.querySelectorAll('[data-sm-read]')].filter(e=>!e.closest('details:not([open])')&&e.getClientRects().length&&getComputedStyle(e).visibility!=='hidden').map(e=>e.innerText).join(' ');el.dataset.speak=spoken(el.dataset.speak);},{capture:true});
}
